import pytest
from calendar_core.slots import Event, fmt_duration, overlaps, parse_time


def test_issue_9am():
    """Check '"9am" -> 540' from the issue examples."""
    assert parse_time("9am") == 540  # 9*60 = 540


def test_issue_9am_spaced_upper():
    """Check '"9 AM" -> 540' with optional space and case-insensitivity."""
    assert parse_time("9 AM") == 540  # 9*60 = 540


def test_issue_230pm():
    """Check '"2:30pm" -> 870' from the issue examples."""
    assert parse_time("2:30pm") == 870  # 14*60+30 = 870


def test_issue_230pm_spaced_upper():
    """Check case-insensitive optional space for '2:30 PM' -> 870."""
    assert parse_time("2:30 PM") == 870  # 14*60+30 = 870


def test_issue_noon():
    """Check '"12pm" -> 720 (noon)' from the issue examples."""
    assert parse_time("12pm") == 720  # 12*60 = 720


def test_issue_midnight():
    """Check '"12am" -> 0 (midnight)' from the issue examples."""
    assert parse_time("12am") == 0  # midnight = 0


def test_issue_quarter_past_midnight():
    """Check '"12:15am" -> 15' from the issue examples."""
    assert parse_time("12:15am") == 15  # 0*60+15 = 15


def test_issue_before_midnight_boundary():
    """Check 12-hour boundary '11:59pm' is the last minute of the day."""
    assert parse_time("11:59pm") == 1439  # 23*60+59 = 1439


def test_issue_invalid_still_raises():
    """Check invalid 12-hour and bare inputs still raise ValueError."""
    for bad in ["13pm", "0am", "9:60am", "9", "pm", ""]:
        with pytest.raises(ValueError):
            parse_time(bad)


def test_contract_24h_afternoon():
    """Check 24-hour 'HH:MM' still parses as before."""
    assert parse_time("14:30") == 870  # 14*60+30 = 870


def test_contract_24h_midnight():
    """Check 24-hour 'HH:MM' still parses midnight '00:00'."""
    assert parse_time("00:00") == 0  # 0*60+0 = 0


def test_contract_fmt_duration():
    """Check fmt_duration renders 'Xh YYm' like 65 -> '1h 05m'."""
    assert fmt_duration(65) == "1h 05m"  # 65 = 1*60+5 -> "1h 05m"


def test_contract_back_to_back_no_overlap():
    """Check back-to-back events do not overlap."""
    assert overlaps(Event(start=0, end=60), Event(start=60, end=120)) is False  # touching at 60 shares no minute
